-- Shared application tables; applied inside app.
CREATE TABLE IF NOT EXISTS "Companies" (
  "CompanyId" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "CompanyName" TEXT NOT NULL,
  "DbDialect" TEXT NOT NULL DEFAULT 'sqlserver',
  "DbName" TEXT NOT NULL,
  "DbUser" TEXT NULL,
  "DbPassword" TEXT NULL,
  "FormQueryDbUser" TEXT NULL,
  "FormQueryDbPassword" TEXT NULL,
  "ServerName" TEXT NULL,
  "LicenseServer" TEXT NULL,
  "SAPVersion" TEXT NULL,
  "IsActive" INTEGER DEFAULT 1,
  "CreatedAt" TEXT DEFAULT CURRENT_TIMESTAMP,
  "Port" INTEGER NULL,
  "AuthDbName" TEXT NULL,
  "SapBaseUrl" TEXT NULL,
  "SapUsername" TEXT NULL,
  "SapPassword" TEXT NULL,
  "SapCompanyDb" TEXT NULL,
  "SapRejectUnauthorized" INTEGER NULL,
  "ReportServiceBaseUrl" TEXT NULL,
  "ReportServiceUsername" TEXT NULL,
  "ReportServicePassword" TEXT NULL,
  "ReportServiceCompanyDb" TEXT NULL,
  "ReportServiceDbInstance" TEXT NULL,
  "ReportServiceDefaultSchema" TEXT NULL,
  "ReportServiceRejectUnauthorized" INTEGER NULL,
  "DbServer" TEXT NULL,
  "DbPort" INTEGER NULL,
  "DbEncrypt" INTEGER NULL,
  "DbTrustCert" INTEGER NULL,
  "SalesOrderDefaultToVendorCode" TEXT NULL
);

CREATE TABLE IF NOT EXISTS "Users" (
  "UserId" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "Username" TEXT NOT NULL UNIQUE,
  "PasswordHash" TEXT NOT NULL,
  "FullName" TEXT NULL,
  "Email" TEXT NULL,
  "IsActive" INTEGER DEFAULT 1,
  "CreatedAt" TEXT DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS "Roles" (
  "RoleId" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "RoleName" TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS "UserCompanies" (
  "Id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "UserId" INTEGER NOT NULL,
  "CompanyId" INTEGER NOT NULL,
  "IsDefault" INTEGER DEFAULT 0,
  "SapUserCode" TEXT NULL,
  FOREIGN KEY ("UserId") REFERENCES "Users"("UserId"),
  FOREIGN KEY ("CompanyId") REFERENCES "Companies"("CompanyId")
);

CREATE TABLE IF NOT EXISTS "UserRoles" (
  "Id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "UserId" INTEGER NOT NULL,
  "RoleId" INTEGER NOT NULL,
  "CompanyId" INTEGER NOT NULL,
  FOREIGN KEY ("UserId") REFERENCES "Users"("UserId"),
  FOREIGN KEY ("RoleId") REFERENCES "Roles"("RoleId"),
  FOREIGN KEY ("CompanyId") REFERENCES "Companies"("CompanyId")
);

CREATE TABLE IF NOT EXISTS "Menus" (
  "MenuId" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "MenuName" TEXT NULL,
  "MenuPath" TEXT NULL,
  "ParentId" INTEGER NULL,
  "Icon" TEXT NULL,
  "SortOrder" NUMERIC NULL,
  "ReportId" INTEGER NULL
);

CREATE TABLE IF NOT EXISTS "RoleRights" (
  "Id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "RoleId" INTEGER NOT NULL,
  "MenuId" INTEGER NOT NULL,
  "CanView" INTEGER DEFAULT 0,
  "CanAdd" INTEGER DEFAULT 0,
  "CanEdit" INTEGER DEFAULT 0,
  "CanDelete" INTEGER DEFAULT 0,
  FOREIGN KEY ("RoleId") REFERENCES "Roles"("RoleId"),
  FOREIGN KEY ("MenuId") REFERENCES "Menus"("MenuId")
);

CREATE TABLE IF NOT EXISTS "ReportMenus" (
  "ReportMenuId" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "MenuName" TEXT NULL,
  "ParentId" INTEGER NULL,
  "Icon" TEXT NULL,
  "SortOrder" INTEGER DEFAULT 0,
  "CreatedBy" INTEGER NULL,
  "CompanyId" INTEGER NULL,
  "CreatedAt" TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "UpdatedAt" TEXT NULL,
  FOREIGN KEY ("ParentId") REFERENCES "ReportMenus"("ReportMenuId")
);

CREATE TABLE IF NOT EXISTS "Reports" (
  "ReportId" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "ReportName" TEXT NULL,
  "ReportCode" TEXT NULL,
  "ApiUrl" TEXT NULL,
  "ReportType" TEXT DEFAULT 'GET',
  "IsActive" INTEGER DEFAULT 1,
  "CreatedAt" TEXT DEFAULT CURRENT_TIMESTAMP,
  "ReportMenuId" INTEGER NULL,
  "CreatedBy" INTEGER NULL,
  "CompanyId" INTEGER NULL,
  "IsPublic" INTEGER NOT NULL DEFAULT 0,
  "UpdatedAt" TEXT NULL,
  FOREIGN KEY ("ReportMenuId") REFERENCES "ReportMenus"("ReportMenuId")
);

CREATE TABLE IF NOT EXISTS "MenuReports" (
  "Id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "MenuId" INTEGER NULL,
  "ReportId" INTEGER NULL,
  FOREIGN KEY ("MenuId") REFERENCES "Menus"("MenuId"),
  FOREIGN KEY ("ReportId") REFERENCES "Reports"("ReportId")
);

CREATE TABLE IF NOT EXISTS "CompanyReports" (
  "Id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "CompanyId" INTEGER NULL,
  "ReportId" INTEGER NULL,
  "IsActive" INTEGER DEFAULT 1,
  FOREIGN KEY ("CompanyId") REFERENCES "Companies"("CompanyId"),
  FOREIGN KEY ("ReportId") REFERENCES "Reports"("ReportId")
);

CREATE TABLE IF NOT EXISTS "ReportParameters" (
  "ParamId" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "ReportId" INTEGER NULL,
  "ParamName" TEXT NULL,
  "DisplayName" TEXT NULL,
  "ParamType" TEXT NULL,
  "IsRequired" INTEGER DEFAULT 0,
  "SortOrder" INTEGER DEFAULT 0,
  "CreatedBy" INTEGER NULL,
  "DefaultValue" TEXT NULL,
  "CreatedAt" TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "UpdatedAt" TEXT NULL,
  FOREIGN KEY ("ReportId") REFERENCES "Reports"("ReportId")
);

CREATE TABLE IF NOT EXISTS "SavedQueryFolders" (
  "FolderId" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "FolderName" TEXT NOT NULL,
  "ParentId" INTEGER NULL,
  "Icon" TEXT NULL,
  "SortOrder" INTEGER NOT NULL DEFAULT 0,
  "CompanyId" INTEGER NOT NULL,
  "CreatedBy" INTEGER NOT NULL,
  "CreatedAt" TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "UpdatedAt" TEXT NULL,
  FOREIGN KEY ("ParentId") REFERENCES "SavedQueryFolders"("FolderId"),
  FOREIGN KEY ("CompanyId") REFERENCES "Companies"("CompanyId"),
  FOREIGN KEY ("CreatedBy") REFERENCES "Users"("UserId")
);

CREATE TABLE IF NOT EXISTS "SavedQueries" (
  "QueryId" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "QueryName" TEXT NOT NULL,
  "FolderId" INTEGER NULL,
  "SqlText" TEXT NOT NULL,
  "RowLimit" INTEGER NOT NULL DEFAULT 500,
  "Description" TEXT NULL,
  "Dialect" TEXT NOT NULL DEFAULT 'sqlserver',
  "IsActive" INTEGER NOT NULL DEFAULT 1,
  "CompanyId" INTEGER NOT NULL,
  "CreatedBy" INTEGER NOT NULL,
  "CreatedAt" TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "UpdatedAt" TEXT NULL,
  "LastRunAt" TEXT NULL,
  FOREIGN KEY ("FolderId") REFERENCES "SavedQueryFolders"("FolderId"),
  FOREIGN KEY ("CompanyId") REFERENCES "Companies"("CompanyId"),
  FOREIGN KEY ("CreatedBy") REFERENCES "Users"("UserId")
);

CREATE TABLE IF NOT EXISTS "UserFormSettings" (
  "FormSettingId" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "UserId" INTEGER NOT NULL,
  "CompanyId" INTEGER NOT NULL,
  "FormKey" TEXT NOT NULL,
  "SettingsJson" TEXT NOT NULL,
  "CreatedAt" TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "UpdatedAt" TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE ("UserId", "CompanyId", "FormKey")
);

CREATE TABLE IF NOT EXISTS "CompanyFormSettings" (
  "CompanyFormSettingId" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "CompanyId" INTEGER NOT NULL,
  "FormKey" TEXT NOT NULL,
  "SettingsJson" TEXT NOT NULL,
  "CreatedByUserId" INTEGER NULL,
  "CreatedAt" TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "UpdatedAt" TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY ("CompanyId") REFERENCES "Companies"("CompanyId"),
  FOREIGN KEY ("CreatedByUserId") REFERENCES "Users"("UserId"),
  UNIQUE ("CompanyId", "FormKey")
);

CREATE TABLE IF NOT EXISTS "CompanyFormQueryLayouts" (
  "CompanyFormQueryLayoutId" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "CompanyId" INTEGER NOT NULL,
  "FormKey" TEXT NOT NULL,
  "QueryText" TEXT NOT NULL,
  "ColumnsJson" TEXT NOT NULL DEFAULT '[]',
  "IsPublished" INTEGER NOT NULL DEFAULT 0,
  "Version" INTEGER NOT NULL DEFAULT 1,
  "PublishedByUserId" INTEGER NULL,
  "PublishedAt" TEXT NULL,
  "CreatedAt" TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "UpdatedAt" TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY ("CompanyId") REFERENCES "Companies"("CompanyId"),
  FOREIGN KEY ("PublishedByUserId") REFERENCES "Users"("UserId"),
  UNIQUE ("CompanyId", "FormKey")
);

CREATE TABLE IF NOT EXISTS "UserGeneralSettings" (
  "UserGeneralSettingId" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "UserId" INTEGER NOT NULL,
  "CompanyId" INTEGER NOT NULL,
  "SettingsJson" TEXT NOT NULL,
  "CreatedAt" TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "UpdatedAt" TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE ("UserId", "CompanyId")
);

CREATE TABLE IF NOT EXISTS "new_sales_order_dummy_drafts" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "dummyDocumentNumber" TEXT NULL UNIQUE,
  "companyId" INTEGER NOT NULL,
  "companyDb" TEXT NOT NULL,
  "userCode" TEXT NOT NULL,
  "schemaVersion" TEXT NOT NULL,
  "formDataJson" TEXT NOT NULL,
  "generatedPayloadJson" TEXT NOT NULL,
  "validationStatus" TEXT NOT NULL DEFAULT 'validated',
  "createdAt" TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updatedAt" TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY ("companyId") REFERENCES "Companies"("CompanyId")
);

CREATE TABLE IF NOT EXISTS "SalesDocumentFieldLookupConfigurations" (
  "LookupConfigurationId" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "CompanyId" INTEGER NOT NULL,
  "DocumentType" TEXT NOT NULL,
  "FieldId" TEXT NOT NULL,
  "LookupSource" TEXT NOT NULL,
  "CreatedByUserId" INTEGER NOT NULL,
  "UpdatedByUserId" INTEGER NOT NULL,
  "CreatedAt" TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "UpdatedAt" TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY ("CompanyId") REFERENCES "Companies"("CompanyId"),
  UNIQUE ("CompanyId", "DocumentType", "FieldId")
);

CREATE TABLE IF NOT EXISTS "sap_form_layout_columns" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "CompanyId" INTEGER NULL,
  "companyDb" TEXT NOT NULL,
  "userCode" TEXT NOT NULL,
  "documentType" TEXT NOT NULL,
  "formType" TEXT NOT NULL,
  "matrixId" TEXT NOT NULL,
  "tableName" TEXT NOT NULL,
  "columnUid" TEXT NOT NULL,
  "fieldName" TEXT,
  "columnTitle" TEXT NOT NULL,
  "visible" INTEGER NOT NULL DEFAULT 1,
  "editable" INTEGER NOT NULL DEFAULT 1,
  "columnOrder" INTEGER NOT NULL DEFAULT 0,
  "width" INTEGER DEFAULT 120,
  "dataType" TEXT,
  "isUdf" INTEGER DEFAULT 0,
  "source" TEXT DEFAULT 'manual',
  "createdAt" TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updatedAt" TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS "sap_form_layout_sync_runs" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "companyDb" TEXT NOT NULL,
  "userCode" TEXT NOT NULL,
  "documentType" TEXT NOT NULL,
  "status" TEXT NOT NULL,
  "message" TEXT,
  "startedAt" TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "completedAt" TEXT
);

CREATE TABLE IF NOT EXISTS "ReportLayoutMenuEntries" (
  "MenuEntryID" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "MenuCode" TEXT NOT NULL UNIQUE,
  "MenuName" TEXT NOT NULL,
  "MenuCategory" TEXT NOT NULL,
  "MenuSequence" INTEGER NULL,
  "ReportCode" TEXT NOT NULL,
  "EntryType" TEXT NOT NULL DEFAULT 'Report',
  "SearchKeywords" TEXT NULL,
  "IsSystem" INTEGER NOT NULL DEFAULT 0,
  "CreatedBy" TEXT NOT NULL,
  "CreatedDate" TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "UpdatedBy" TEXT NULL,
  "UpdatedDate" TEXT NULL
);

CREATE TABLE IF NOT EXISTS "ReportLayouts" (
  "LayoutID" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "MenuEntryID" INTEGER NULL,
  "LayoutName" TEXT NOT NULL,
  "ReportCode" TEXT NOT NULL,
  "LayoutJSON" TEXT NOT NULL,
  "IsDefault" INTEGER NOT NULL DEFAULT 0,
  "AssignedUserId" INTEGER NULL,
  "AssignedRoleId" INTEGER NULL,
  "CreatedBy" TEXT NOT NULL,
  "CreatedDate" TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "UpdatedBy" TEXT NULL,
  "UpdatedDate" TEXT NULL,
  FOREIGN KEY ("MenuEntryID") REFERENCES "ReportLayoutMenuEntries"("MenuEntryID")
);

CREATE TABLE IF NOT EXISTS "ReportLayoutVersions" (
  "VersionID" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "LayoutID" INTEGER NOT NULL,
  "VersionNo" INTEGER NOT NULL,
  "LayoutJSON" TEXT NOT NULL,
  "ChangeNote" TEXT NULL,
  "ChangedBy" TEXT NOT NULL,
  "ChangedDate" TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY ("LayoutID") REFERENCES "ReportLayouts"("LayoutID")
);

CREATE INDEX IF NOT EXISTS "IX_SavedQueryFolders_CompanyOwner"
  ON "SavedQueryFolders" ("CompanyId", "CreatedBy", "ParentId", "SortOrder", "FolderName");
CREATE INDEX IF NOT EXISTS "IX_SavedQueries_CompanyFolder"
  ON "SavedQueries" ("CompanyId", "FolderId", "IsActive", "QueryName");
CREATE INDEX IF NOT EXISTS "IX_RLME_Category"
  ON "ReportLayoutMenuEntries" ("MenuCategory", "MenuName", "ReportCode");
CREATE INDEX IF NOT EXISTS "IX_ReportLayouts_MenuEntry"
  ON "ReportLayouts" ("MenuEntryID", "ReportCode", "IsDefault");
CREATE INDEX IF NOT EXISTS "IX_ReportLayoutVersions_LayoutID"
  ON "ReportLayoutVersions" ("LayoutID", "VersionNo");
CREATE INDEX IF NOT EXISTS "IX_ReportMenus_CompanyOwner"
  ON "ReportMenus" ("CompanyId", "CreatedBy", "ParentId", "SortOrder", "MenuName");
CREATE INDEX IF NOT EXISTS "IX_ReportParameters_Report"
  ON "ReportParameters" ("ReportId", "SortOrder", "ParamId");
CREATE INDEX IF NOT EXISTS "IX_Reports_CompanyOwner"
  ON "Reports" ("CompanyId", "CreatedBy", "IsPublic", "ReportMenuId", "ReportName");
CREATE INDEX IF NOT EXISTS "IX_sap_form_layout_columns_lookup"
  ON "sap_form_layout_columns" ("companyDb", "userCode", "documentType", "formType", "matrixId", "columnOrder", "id");
CREATE INDEX IF NOT EXISTS "IX_sap_form_layout_sync_runs_lookup"
  ON "sap_form_layout_sync_runs" ("companyDb", "userCode", "documentType", "startedAt");
CREATE INDEX IF NOT EXISTS "IX_new_sales_order_dummy_drafts_scope"
  ON "new_sales_order_dummy_drafts" ("companyId", "userCode", "createdAt", "id");
CREATE UNIQUE INDEX IF NOT EXISTS "UX_new_sales_order_dummy_drafts_number"
  ON "new_sales_order_dummy_drafts" ("dummyDocumentNumber");
CREATE INDEX IF NOT EXISTS "IX_SalesDocumentFieldLookupConfigurations_Scope"
  ON "SalesDocumentFieldLookupConfigurations" ("CompanyId", "DocumentType", "FieldId");

CREATE TABLE IF NOT EXISTS "SalesDocumentCustomLookups" (
  "CustomLookupId" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "CompanyId" INTEGER NOT NULL,
  "LookupName" TEXT NOT NULL,
  "QueryText" TEXT NOT NULL,
  "CreatedByUserId" INTEGER NOT NULL,
  "UpdatedByUserId" INTEGER NOT NULL,
  "CreatedAt" TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "UpdatedAt" TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY ("CompanyId") REFERENCES "Companies"("CompanyId"),
  FOREIGN KEY ("CreatedByUserId") REFERENCES "Users"("UserId"),
  FOREIGN KEY ("UpdatedByUserId") REFERENCES "Users"("UserId"),
  UNIQUE ("CompanyId", "LookupName")
);
CREATE INDEX IF NOT EXISTS "IX_SalesDocumentCustomLookups_Company"
  ON "SalesDocumentCustomLookups" ("CompanyId", "LookupName");
CREATE INDEX IF NOT EXISTS "IX_sap_form_layout_columns_company" ON "sap_form_layout_columns" ("CompanyId", "documentType", "formType", "matrixId", "columnOrder", "id");
CREATE UNIQUE INDEX IF NOT EXISTS "UX_sap_form_layout_columns_company_scope" ON "sap_form_layout_columns" ("CompanyId", "companyDb", "userCode", "documentType", "formType", "matrixId", "columnUid");

-- COMPANY ADDONS
-- Applied inside app_company_<CompanyId> to preserve isolation.
CREATE TABLE IF NOT EXISTS "qc_addons" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "addon_code" TEXT NOT NULL UNIQUE,
  "addon_name" TEXT NOT NULL,
  "version" TEXT NOT NULL,
  "status" TEXT NOT NULL DEFAULT 'active',
  "description" TEXT,
  "installed_on" TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS "qc_document_mappings" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "document_type" TEXT NOT NULL,
  "document_code" TEXT NOT NULL,
  "qc_workflow" TEXT NOT NULL,
  "inspection_level" TEXT NOT NULL,
  "mandatory_inspection" INTEGER NOT NULL DEFAULT 0,
  "block_outward_if_failed" INTEGER NOT NULL DEFAULT 0,
  "is_active" INTEGER NOT NULL DEFAULT 1,
  "created_at" TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE("document_type", "document_code")
);

CREATE TABLE IF NOT EXISTS "qc_parameters" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "parameter_code" TEXT NOT NULL UNIQUE,
  "parameter_name" TEXT NOT NULL,
  "parameter_type" TEXT NOT NULL,
  "uom" TEXT,
  "test_method" TEXT,
  "is_ctq" INTEGER NOT NULL DEFAULT 0,
  "spec_min" REAL,
  "spec_max" REAL,
  "spec_target" REAL,
  "allowed_values" TEXT,
  "created_at" TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS "qc_workflows" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "workflow_name" TEXT NOT NULL UNIQUE,
  "workflow_type" TEXT NOT NULL,
  "trigger_event" TEXT NOT NULL,
  "assigned_inspector" TEXT NOT NULL,
  "approval_required" TEXT NOT NULL DEFAULT 'No Approval',
  "is_active" INTEGER NOT NULL DEFAULT 1,
  "created_at" TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS "qc_transactions" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "transaction_no" TEXT NOT NULL UNIQUE,
  "direction" TEXT NOT NULL,
  "source_type" TEXT NOT NULL,
  "source_doc_no" TEXT,
  "source_doc_entry" INTEGER,
  "source_line_num" INTEGER,
  "party_name" TEXT,
  "item_code" TEXT NOT NULL,
  "lot_no" TEXT,
  "quantity" REAL NOT NULL,
  "uom" TEXT,
  "inspection_status" TEXT NOT NULL DEFAULT 'Open',
  "final_decision" TEXT NOT NULL DEFAULT 'Pending',
  "inspector_name" TEXT,
  "inspection_date" TEXT,
  "remarks" TEXT,
  "created_at" TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS "qc_item_parameter_mappings" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "item_code" TEXT NOT NULL,
  "item_name" TEXT,
  "parameter_code" TEXT NOT NULL,
  "parameter_name" TEXT,
  "instrument_code" TEXT,
  "instrument_name" TEXT,
  "uom" TEXT,
  "parameter_type" TEXT,
  "rule_name" TEXT,
  "from_value" TEXT,
  "to_value" TEXT,
  "expected_value" TEXT,
  "is_optional" INTEGER NOT NULL DEFAULT 0,
  "remarks" TEXT,
  "is_active" INTEGER NOT NULL DEFAULT 1,
  "user_name" TEXT,
  "document_no" TEXT,
  "so_num" TEXT,
  "so_key" TEXT,
  "created_at" TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE("item_code", "parameter_code")
);

CREATE TABLE IF NOT EXISTS "qc_instruments" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "instrument_code" TEXT NOT NULL UNIQUE,
  "instrument_name" TEXT NOT NULL,
  "remarks" TEXT,
  "is_active" INTEGER NOT NULL DEFAULT 1,
  "created_at" TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS "whatsapp_customers" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "phone_number" TEXT UNIQUE NOT NULL,
  "card_code" TEXT,
  "display_name" TEXT,
  "created_at" TEXT DEFAULT CURRENT_TIMESTAMP,
  "updated_at" TEXT DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS "whatsapp_conversations" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "customer_id" INTEGER NOT NULL REFERENCES "whatsapp_customers"("id"),
  "status" TEXT NOT NULL DEFAULT 'open',
  "assigned_user_id" INTEGER,
  "last_message_at" TEXT,
  "created_at" TEXT DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS "whatsapp_messages" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "conversation_id" INTEGER NOT NULL REFERENCES "whatsapp_conversations"("id"),
  "direction" TEXT NOT NULL,
  "message_type" TEXT NOT NULL,
  "body" TEXT,
  "wamid" TEXT,
  "sent_by_user_id" INTEGER,
  "is_bot" INTEGER DEFAULT 0,
  "created_at" TEXT DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS "whatsapp_templates" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" TEXT UNIQUE NOT NULL,
  "language_code" TEXT NOT NULL DEFAULT 'en_US',
  "category" TEXT,
  "body_preview" TEXT,
  "created_at" TEXT DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS "whatsapp_broadcasts" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "template_id" INTEGER REFERENCES "whatsapp_templates"("id"),
  "created_by_user_id" INTEGER,
  "status" TEXT NOT NULL DEFAULT 'draft',
  "created_at" TEXT DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS "whatsapp_broadcast_recipients" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "broadcast_id" INTEGER NOT NULL REFERENCES "whatsapp_broadcasts"("id"),
  "customer_id" INTEGER NOT NULL REFERENCES "whatsapp_customers"("id"),
  "status" TEXT NOT NULL DEFAULT 'pending',
  "error_detail" TEXT,
  "sent_at" TEXT
);

CREATE TABLE IF NOT EXISTS "whatsapp_message_templates" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "document_type" TEXT UNIQUE NOT NULL,
  "template_body" TEXT NOT NULL,
  "is_active" INTEGER NOT NULL DEFAULT 1,
  "created_at" TEXT DEFAULT CURRENT_TIMESTAMP,
  "updated_at" TEXT DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS "whatsapp_audit_log" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "user_id" INTEGER,
  "action" TEXT NOT NULL,
  "detail" TEXT,
  "created_at" TEXT DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX IF NOT EXISTS "idx_whatsapp_conversations_customer" ON "whatsapp_conversations"("customer_id");
CREATE INDEX IF NOT EXISTS "idx_whatsapp_messages_conversation" ON "whatsapp_messages"("conversation_id");
CREATE UNIQUE INDEX IF NOT EXISTS "UX_whatsapp_open_customer"
  ON "whatsapp_conversations" ("customer_id") WHERE "status" <> 'closed';
